SELECT id, username, user_type, enabled, authorization_version
FROM iam_user WHERE id > #{afterUserId}
ORDER BY id LIMIT #{limit}

SELECT id, username, user_type, enabled, authorization_version
FROM iam_user
WHERE id > #{afterUserId}

    AND username LIKE CONCAT('%', #{username}, '%')


    AND user_type = #{userType}


    AND enabled = #{enabled}

ORDER BY id LIMIT #{limit}
